<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireLogin();if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::validate($_POST['csrf_token']??null)){header('Location: /leads/?resultado=erro');exit;}$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0;$pdo=Database::connection();$q=$pdo->prepare('SELECT * FROM leads WHERE id=:id AND cliente_id IS NULL');$q->execute(['id'=>$id]);$lead=$q->fetch();if(!$lead){header('Location: /leads/?resultado=erro');exit;}if(!$lead['cnpj']){header('Location: /leads/?resultado=pendente');exit;}$q=$pdo->prepare('SELECT id FROM clientes WHERE documento=:cnpj');$q->execute(['cnpj'=>$lead['cnpj']]);if($q->fetch()){header('Location: /leads/?resultado=duplicado');exit;}
try{$pdo->beginTransaction();$insert=$pdo->prepare('INSERT INTO clientes(documento,razao_social,nome_fantasia,telefone,email,cep,logradouro,numero,complemento,bairro,cidade,estado,latitude,longitude,observacoes,ativo) VALUES(:documento,:razao,:fantasia,:telefone,:email,:cep,:logradouro,:numero,:complemento,:bairro,:cidade,:estado,:latitude,:longitude,:observacoes,1)');$insert->execute(['documento'=>$lead['cnpj'],'razao'=>$lead['razao_social']?:$lead['nome_fantasia'],'fantasia'=>$lead['nome_fantasia'],'telefone'=>$lead['telefone'],'email'=>$lead['email'],'cep'=>$lead['cep'],'logradouro'=>$lead['logradouro'],'numero'=>$lead['numero'],'complemento'=>$lead['complemento'],'bairro'=>$lead['bairro'],'cidade'=>$lead['cidade'],'estado'=>$lead['estado'],'latitude'=>$lead['latitude'],'longitude'=>$lead['longitude'],'observacoes'=>$lead['observacoes']]);$clienteId=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE leads SET cliente_id=:cliente,status='convertido' WHERE id=:id")->execute(['cliente'=>$clienteId,'id'=>$id]);$pdo->commit();header('Location: /leads/?resultado=convertido');}catch(Throwable){if($pdo->inTransaction())$pdo->rollBack();header('Location: /leads/?resultado=erro');}exit;
